package com.fream.back.domain.notification.service.command;

import com.fream.back.domain.notification.entity.NotificationCategory;
import com.fream.back.domain.notification.entity.NotificationType;
import com.fream.back.domain.product.entity.Interest;
import com.fream.back.domain.product.repository.InterestRepository;
import com.fream.back.domain.sale.event.SaleBidCreatedEvent;
import lombok.RequiredArgsConstructor;
import org.springframework.context.event.EventListener;
import org.springframework.stereotype.Component;

import java.util.List;

/**
 * 새 판매 입찰이 등록되면 같은 색상을 관심 등록한 회원에게 알림을 보낸다.
 * 판매자 본인과 비활성화된 회원은 제외한다.
 */
@Component
@RequiredArgsConstructor
public class NewListingAlertListener {

    private final InterestRepository interestRepository;
    private final NotificationCommandService notificationCommandService;

    @EventListener
    public void onSaleBidCreated(SaleBidCreatedEvent event) {
        List<Interest> interests = interestRepository.findAllByProductColorId(event.productColorId());

        interests.stream()
                .map(Interest::getUser)
                .filter(user -> user != null)
                .filter(user -> !user.getId().equals(event.sellerId()))
                .filter(user -> user.isActive())
                .map(user -> user.getId())
                .distinct()
                .forEach(userId -> notificationCommandService.createNotification(
                        userId,
                        NotificationCategory.SHOPPING,
                        NotificationType.FAVORITE,
                        String.format("관심 상품 '%s' 사이즈 %s에 새 판매 입찰이 등록되었습니다. 판매 희망가: %d원",
                                event.productName(), event.size(), event.bidPrice())
                ));
    }
}
EOF
